
'use strict';
const $=(id)=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x)), id=()=>crypto.randomUUID();
// Panel times are wall times in the session's timezone (state.timezone): the zone this browser reported at sign-in,
// or the server's control.timezone when it reported none the server knows.
let zone='UTC';
const zoneFormats=new Map();
function zoneOffset(ms){try{let f=zoneFormats.get(zone);if(!f){f=new Intl.DateTimeFormat('en-US',{timeZone:zone,hourCycle:'h23',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'});zoneFormats.set(zone,f);}const p={};for(const x of f.formatToParts(new Date(ms)))p[x.type]=x.value;return Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second)-Math.floor(ms/1000)*1000;}catch{return 0;}}
const dateMs=s=>{const t=Date.parse(s+(s.length===16?':00':'')+'Z');return Number.isFinite(t)?t-zoneOffset(t-zoneOffset(t)):NaN;}, wallTime=ms=>new Date(ms+zoneOffset(ms)).toISOString().slice(0,16), nowLocal=()=>wallTime(Date.now()), relativeTime=hours=>wallTime(Date.now()+hours*3600000);
function zoneLabel(){const m=Math.round(zoneOffset(Date.now())/60000),a=Math.abs(m);return zone+' (UTC'+(m<0?'−':'+')+String(Math.floor(a/60)).padStart(2,'0')+':'+String(a%60).padStart(2,'0')+')';}
function renderZone(){document.querySelectorAll('[data-tz]').forEach(n=>n.textContent=zone);document.querySelectorAll('[data-tz-full]').forEach(n=>n.textContent=zoneLabel());}
function art(title,index){const colors=[['#4048ca','#ff4fb8'],['#fb8348','#6728b9'],['#247bbd','#76e4c0'],['#9e3eff','#ff78b7'],['#cf4770','#ffad64'],['#234b9e','#87a9ff'],['#657638','#e1d575'],['#7445bf','#57d7ce']][index%8];return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="500" height="600" viewBox="0 0 500 600"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="${colors[0]}"/><stop offset="1" stop-color="${colors[1]}"/></linearGradient></defs><rect width="500" height="600" fill="url(#g)"/><path d="M-100 450L550 -40M-100 540L580 30M-100 630L610 100" stroke="#ffffff" stroke-opacity=".13" stroke-width="50"/><circle cx="250" cy="255" r="156" fill="#10071e" opacity=".85"/><circle cx="250" cy="255" r="130" fill="none" stroke="#ffffff" stroke-opacity=".18"/><circle cx="250" cy="255" r="110" fill="none" stroke="#ffffff" stroke-opacity=".1"/><circle cx="250" cy="255" r="55" fill="${colors[1]}"/><circle cx="250" cy="255" r="8" fill="#10071e"/><text x="30" y="55" fill="#ffffff" font-family="sans-serif" font-size="18" letter-spacing="4">FUSER COMMUNITY</text></svg>`);}
function initial(){return {version:1,items:Array.from({length:8},()=>({id:'',title:'',artist:'',shortname:'',price:0,enabled:false,start:relativeTime(-24),end:relativeTime(168),image:''})),users:[],exemptions:[],events:[],promotions:[]};}
let state=initial(),baseline=null,saving=false,admins={self:'',admins:[],tokens:[],audit:[]};
function reconcilePromotion(p){return {promotion_id:p.promotion_id||0,promotion_type:'hmx_promotion',name:p.name??p.title??'Community announcement',message:p.message??p.body??'',extra_text:p.extra_text??p.body??'',enabled:p.enabled,start:p.start,end:p.end,image:p.image||''};}
state.promotions=(state.promotions||[]).map(reconcilePromotion);
let toastTimer,editing=null,promoDraft=null,promoBase=null,promoIndex=0,promoVersion=null,confirmCallback=null;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
async function request(path,method='GET',value,version){const response=await fetch('/control/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(version?{'If-Match':version}:{})},body:value===undefined?undefined:JSON.stringify(value)});if(response.status===401){location.reload();throw new Error('Sign in required');}const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data;}
async function refresh(){[state,admins]=await Promise.all([request('api/state'),request('api/admins')]);zone=state.timezone||'UTC';state.promotions=(state.promotions||[]).map(reconcilePromotion);baseline=clone(state);loadPromotion();render();$('save-status').textContent='Connected · changes apply to the live server';if(!state.exemptions_enabled)$('save-status').textContent+=' · Epic exemptions are disabled in server configuration';}
async function save(message,versions=baseline?.versions){if(!baseline||saving)return;saving=true;document.querySelector('.shell').inert=true;$('editor').inert=true;$('save-status').textContent='Saving…';try{
 for(const resource of ['items','promotions'])if(JSON.stringify(state[resource])!==JSON.stringify(baseline[resource]))await request('api/'+resource,'PUT',state[resource],versions[resource]);
 for(const resource of ['events','users','exemptions']){const previous=baseline[resource];for(const old of previous)if(!state[resource].some(x=>x.id===old.id)&&resource!=='users')await request('api/'+resource+'/'+encodeURIComponent(old.id),'DELETE');for(const current of state[resource]){const old=previous.find(x=>x.id===current.id);if(JSON.stringify(old)===JSON.stringify(current))continue;const value=clone(current);if(resource==='events'&&!old)value.id='';await request('api/'+resource,'PUT',resource==='events'?{value,before:editing?.kind==='event'&&editing.draft.id===current.id?editing.before.slots:old?.slots||[]}:resource==='exemptions'?{old:old?.key||'',value}:value);}}
 await refresh();if(message)toast(message.replace('to the preview','to the server').replace('in preview','on the server'));return true;
 }catch(error){toast('Save failed: '+error.message);try{await refresh();}catch{$('save-status').textContent='Disconnected · reload to retry';}return false;}finally{saving=false;document.querySelector('.shell').inert=false;$('editor').inert=false;}}
function name(user){return state.users.find(u=>u.id===Number(user))?.name||'Unknown player';}
function eventStatus(e){return dateMs(e.end)<=Date.now()?'ended':dateMs(e.start)<=Date.now()?'live':'upcoming';}
function badge(status){return `<span class="badge ${status==='live'||status==='online'?'live':status==='banned'?'banned':''}">${status==='live'||status==='online'?'<span class="dot"></span>':''}${{live:'Live now',upcoming:'Upcoming',ended:'Ended',online:'Online',offline:'Offline',banned:'Banned'}[status]||esc(status)}</span>`;}
function eventArt(e){if(e.image)return `<img class="event-thumb" src="${esc(e.image)}" alt="${esc(e.name)} event artwork">`;return generatedCard(e);}
function generatedCard(e){const people=e.slots.filter(s=>s.user);return `<div class="generated-card"><h3>${esc(e.name)}</h3><small>Headliners</small><div class="portraits">${people.length?people.map(s=>`<div class="portrait"><i>${esc(name(s.user).slice(0,1))}</i><span>${esc(name(s.user).split('#')[0])}</span></div>`).join(''):'<small>No headliners yet</small>'}</div></div>`;}
function assetOptions(selected){return '<option value="">Choose an available asset</option>'+state.assets.map(a=>`<option value="${esc(a.id)}" ${a.id===selected?'selected':''}>${esc(a.title)} · ${esc(a.artist)} (${esc(a.type)})</option>`).join('');}
function renderAssets(){const query=$('asset-search').value.toLowerCase();$('asset-count').textContent=state.assets.length+' assets';$('asset-list').innerHTML=state.assets.filter(a=>(a.title+' '+a.artist+' '+a.shortname).toLowerCase().includes(query)).map(a=>{const slots=state.items.map((it,i)=>it.assetId===a.id?i+1:null).filter(Boolean);return `<article class="asset-row"><img src="${esc(a.image||art(a.title,0))}" alt=""><div><strong>${esc(a.title)}</strong><small>${esc(a.artist)} · ${esc(a.type)}</small><small class="key">${esc(a.shortname)}</small><small>${esc(a.filename)}${a.size!==null?' · '+(a.size/1024/1024).toFixed(2)+' MB':''}${a.signature?' · signature included':''}</small><span class="badge ${slots.length?'live':''}">${slots.length?'Linked to slot '+slots.join(', '):'Ready to select'}</span></div><div class="actions"><button type="button" data-remove-asset="${esc(a.id)}" ${slots.length?'disabled title="Clear or change linked offers first"':''}>Remove</button></div></article>`;}).join('')||'<p class="empty">No assets match your search.</p>';}

function renderStore(){$('store-grid').innerHTML=state.items.map((it,i)=>`<button class="store-card ${i<2?'featured':''} ${!it.enabled?'off':''}" data-item="${i}" aria-label="Edit slot ${i+1}: ${esc(it.title||'Empty slot')}">${it.image?`<img src="${esc(it.image)}" alt="">`:''}<span class="position">${i<2?'FEATURED':'STANDARD'} ${i+1}${!it.enabled?' · OFF':''}</span><div class="item-info"><strong>${esc(it.title||'Empty slot')}</strong><small>${esc(it.artist||'Click to add an item')}</small><span class="price">◇ ${it.price||0}</span><span class="edit-cue">Edit ↗</span></div></button>`).join('');}
function renderSchedule(){const counts=['live','upcoming','ended'].map(k=>state.events.filter(e=>eventStatus(e)===k).length);$('schedule-stats').innerHTML=counts.map((n,i)=>`<div class="stat"><strong>${n}</strong><span>${['Live now','Upcoming events','Ended'][i]}</span></div>`).join('');const hold=state.hold_current_minutes||0;$('schedule-hold').hidden=!state.schedule_enabled;$('schedule-hold').textContent=hold?`Between sets, FUSER keeps showing the last event that ended as the current event until the next event starts, for at most ${hold} min (main_stage.hold_current_minutes). The game then shows that event's image but no headliners. Maintenance windows are never held, and the Main Stage server, joining and the website follow the real times.`:'Holding the last event between sets is off (main_stage.hold_current_minutes = 0): between sets, FUSER\'s Diamond Stage tiles show no text.';const filter=$('schedule-filter').value;const events=[...state.events].sort((a,b)=>dateMs(a.start)-dateMs(b.start)).filter(e=>filter==='all'||(filter==='not-ended'?eventStatus(e)!=='ended'||e.held_until:eventStatus(e)===filter));$('schedule-list').innerHTML=events.map(e=>`<article class="event-row panel"><div>${eventArt(e)}</div><div class="event-info">${badge(eventStatus(e))}${e.held_until?` <span class="badge held" title="FUSER shows this event as the current one until the next event starts">Shown as current in FUSER until ${esc(e.held_until.replace('T',' · '))}</span>`:''}<h3>${esc(e.name)}</h3><p>${esc(e.start.replace('T',' · '))} → ${esc(e.end.replace('T',' · '))}</p><small>${e.type==='maintenance'?'Maintenance':e.type==='special_event'?'Special event':'Standard event'} · ${e.turn?e.turn+' min per turn':'Auto turn length'}${e.allow_stock?' · Stock players allowed':''}</small><div class="slot-summary">${e.slots.map((s,i)=>`<span class="slot-chip ${s.blocked?'blocked':s.user?'filled':''}">${i+1} · ${s.blocked?'Blocked':s.user?esc(name(s.user).split('#')[0]):'Open'}</span>`).join('')}</div></div><div class="actions"><button data-event="${e.id}">Edit event</button><button data-duplicate="${e.id}">Duplicate</button><button class="danger" data-remove-event="${e.id}">Remove</button></div></article>`).join('')||'<div class="panel empty"><h3>No events here</h3><p>Add an event or change the filter.</p></div>';}
function renderUsers(){const search=$('user-search').value.toLowerCase(),filter=$('user-filter').value;const list=state.users.filter(u=>(u.name+' '+u.id+' '+u.key).toLowerCase().includes(search)&&(filter==='all'||filter==='banned'&&u.banned||filter==='online'&&u.online&&!u.banned||filter==='offline'&&!u.online&&!u.banned));$('user-count').textContent=list.length+' of '+state.users.length+' users';$('user-stats').innerHTML=[['Total users',state.users.length],['Online',state.users.filter(u=>u.online&&!u.banned).length],['Banned',state.users.filter(u=>u.banned).length]].map(([t,n])=>`<div class="stat"><strong>${n}</strong><span>${t}</span></div>`).join('');$('user-list').innerHTML=list.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>ID ${u.id}</small></td><td>${esc(u.platform)}<small class="key">${esc(u.key)}</small></td><td>${badge(u.banned?'banned':u.online?'online':'offline')}</td><td>${esc(u.lastSeen.replace('T',' '))}</td><td><div class="actions"><button data-user="${u.id}">Edit</button><button class="${u.banned?'':'danger'}" data-ban="${u.id}">${u.banned?'Unban':'Ban'}</button></div></td></tr>`).join('')||'<tr><td colspan="5">No users match your search.</td></tr>';}
function renderExemptions(){const query=$('exemption-search').value.toLowerCase(),list=state.exemptions.filter(e=>(e.username+' '+e.key).toLowerCase().includes(query));$('exemption-count').textContent=list.length+' exemptions';$('exemption-list').innerHTML=list.map(e=>`<tr><td><strong>${esc(e.username)}</strong></td><td class="key">${esc(e.key)}</td><td>${esc(e.notes)}</td><td><div class="actions"><button data-exemption="${e.id}">Edit</button><button class="danger" data-remove-exemption="${e.id}">Remove</button></div></td></tr>`).join('')||'<tr><td colspan="4">No exemptions match your search.</td></tr>';}
function render(){renderZone();renderCommunityNav(state.community_songs);renderAssets();renderStore();renderSchedule();renderUsers();renderExemptions();renderPromotionList();renderPromotionPreview();renderAdmins();}
function activate(page){document.querySelectorAll('[data-page]').forEach(t=>{const active=t.dataset.page===page;t.setAttribute('aria-selected',active);t.tabIndex=active?0:-1;$(t.getAttribute('aria-controls')).hidden=!active;});if(page==='promotion')requestAnimationFrame(fitPromotionText);if(page==='status')startStatus();else stopStatus();if(page==='community')loadCommunity();}let statusTimer=null;function startStatus(){stopStatus();loadStatus();statusTimer=setInterval(()=>{if(!document.hidden)loadStatus();},10000);}function stopStatus(){if(statusTimer)clearInterval(statusTimer);statusTimer=null;}async function loadStatus(){try{renderStatus(await request('api/status'));}catch(error){$('status-updated').textContent='Status unavailable: '+error.message;$('status-updated').className='badge banned';}}function renderStatus(st){$('status-updated').textContent='Updated '+st.updated;$('status-updated').className='badge live';$('status-stats').innerHTML=[['Online',st.online],['Performing',st.performers],['Watching',st.viewers],['In public lobbies',st.in_public],['In private lobbies',st.in_private],['Elsewhere',st.elsewhere]].map(([label,n])=>`<div class="stat"><strong>${n}</strong><span>${label}</span></div>`).join('');$('status-lobbies').innerHTML=st.lobbies.map(l=>{const set=l.rounds?`${l.rounds} round${l.rounds>1?'s':''} × ${l.bars} bars · `:'';const members=l.members.map(m=>{const known=state.users.some(u=>u.id===m.id);return `<tr><td><strong>${esc(m.name)}</strong><small>ID ${m.id}${m.creator?' · creator':''}</small></td><td>${m.role==='performer'?'Performer':'Viewer'}</td><td>${esc(m.joined)}</td><td>${known?`<button type="button" data-user="${m.id}">Open user</button>`:''}</td></tr>`;}).join('')||'<tr><td colspan="4">Nobody in this lobby has been seen online in the last minute.</td></tr>';return `<article class="panel status-lobby"><div class="status-head">${l.image?`<img class="status-venue" src="${esc(l.image)}" alt="">`:''}<div><h3>${esc(l.title)} <span class="badge${l.private?' private':''}">${l.private?'Private':'Public'}</span> <span class="badge status-${esc(l.state_class)}">${esc(l.state)}</span></h3><p>${esc(l.venue)}${l.time_of_day?' · '+esc(l.time_of_day):''}</p><small>${set}${l.players}${l.capacity?' / '+l.capacity:''} players · ${l.performers} performing · ${l.viewers} watching</small><small class="key">Created ${esc(l.created)} · session ${esc(l.session)} · server ${esc(l.slot)}</small></div></div><div class="table-wrap"><table><thead><tr><th>Player</th><th>Role</th><th>Joined (<span data-tz>${esc(zone)}</span>)</th><th>Actions</th></tr></thead><tbody>${members}</tbody></table></div></article>`;}).join('')||'<div class="panel empty"><h3>No lobbies running</h3><p>No public or private FDS lobby is up right now.</p></div>';}
document.querySelectorAll('[data-page]').forEach((t,i,tabs)=>{t.onclick=()=>activate(t.dataset.page);t.onkeydown=e=>{let ix;if(['ArrowRight','ArrowDown'].includes(e.key))ix=(i+1)%tabs.length;if(['ArrowLeft','ArrowUp'].includes(e.key))ix=(i+tabs.length-1)%tabs.length;if(e.key==='Home')ix=0;if(e.key==='End')ix=tabs.length-1;if(ix!==undefined){e.preventDefault();activate(tabs[ix].dataset.page);tabs[ix].focus();}};});
function confirmChange(title,copy,action,callback){$('confirm-title').textContent=title;$('confirm-copy').textContent=copy;$('confirm-action').textContent=action;confirmCallback=callback;$('confirm-reason-wrap').hidden=true;$('confirm-dialog').showModal();}
$('confirm-cancel').onclick=()=>{$('confirm-dialog').close();confirmCallback=null;};$('confirm-action').onclick=()=>{const callback=confirmCallback;$('confirm-dialog').close();confirmCallback=null;callback?.();};
function imageControl(image,target){return `${image?`<img src="${esc(image)}" alt="Selected image preview">`: '<p class="helper">No custom image</p>'}<div class="actions"><label class="upload">${image?'Replace image':'Upload image'}<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-upload="${target}"></label>${image?`<button type="button" data-clear-image="${target}">Remove image</button>`:''}</div>`;}
function fields(values,spec){return spec.map(([key,label,type='text',extra=''])=>`<label ${extra==='wide'?'class="wide"':''}>${label}${type==='textarea'?`<textarea name="${key}">${esc(values[key])}</textarea>`:`<input name="${key}" type="${type}" ${type==='datetime-local'?'step="1"':''} value="${esc(values[key])}" ${extra!=='wide'?extra:''}>`}</label>`).join('');}
function openEditor(kind,data,index){editing={kind,draft:clone(data),before:clone(data),versions:clone(state.versions),index,originIndex:index};$('editor-title').textContent={item:'Edit store slot '+(index+1),event:data.id?'Edit event':'Add event',user:'Edit user',exemption:data.id?'Edit exemption':'Add exemption'}[kind];$('editor-secondary').innerHTML=kind==='item'?'<button type="button" id="move-left">← Move earlier</button><button type="button" id="move-right">Move later →</button><button type="button" class="danger" id="clear-item">Clear slot</button>':'';renderEditor();$('editor').showModal();}
function renderEditor(){const {kind,draft:d}=editing;let body='';if(kind==='item'){body=`<div class="editor-layout"><div><div class="form-grid"><label class="wide">Asset to publish<select name="assetId" required>${assetOptions(d.assetId)}</select></label><p class="asset-selection-note">Choose from the asset library. Price, dates and availability belong to this offer.</p>${fields(d,[['title','Item name','text','required maxlength="80"'],['artist','Artist','text','required maxlength="80"'],['shortname','Asset shortname','text','readonly required'],['price','Diamond price','number','required min="0" max="999999" step="1"'],['start','Starts ('+esc(zone)+')','datetime-local','required'],['end','Ends ('+esc(zone)+')','datetime-local','required']])}<label class="wide check"><input type="checkbox" name="enabled" ${d.enabled?'checked':''}>Available in store</label><div class="wide"><label>Item artwork</label><div class="image-control">${imageControl(d.image,'editor')}</div></div></div></div><aside class="editor-preview"><div class="preview-caption">Item preview</div><div id="item-live-preview"></div><p class="helper">Position ${editing.index+1} · ${editing.index<2?'Featured':'Standard'}</p>${editing.index<2?'<p class="helper">Featured tiles are 8:15 portrait (396 × 741). Artwork of another shape, the album art included, is centre-cropped to 8:15 in FUSER.</p>':''}</aside></div>`;}else if(kind==='event'){body=`<div class="editor-layout"><div><div class="form-grid">${fields(d,[['name','Event name','text','required maxlength="100"'],['special_name','Special event title','text','maxlength="100"'],['special_type_name','Special event subtitle','text','maxlength="100"'],['special_description','Special event description','textarea','wide']])}<label>Event type<select name="type"><option value="event" ${d.type==='event'?'selected':''}>Standard event</option><option value="special_event" ${d.type==='special_event'?'selected':''}>Special event</option><option value="maintenance" ${d.type==='maintenance'?'selected':''}>Maintenance</option></select></label><p class="helper wide">After a standard or special event ends, FUSER keeps showing it as the current event until the next event starts${state.hold_current_minutes?' (at most '+state.hold_current_minutes+' min)':' (off on this server)'}. A maintenance window is never held, so the game's join isn't blocked once it ends.</p>${fields(d,[['start','Starts ('+esc(zone)+')','datetime-local','required'],['end','Ends ('+esc(zone)+')','datetime-local','required'],['turn','Minutes per turn (0 = auto)','number','min="0" max="60" required']])}<label>Headliner slots<select id="slot-count" name="slotCount">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${d.slots.length===i+1?'selected':''}>${i+1} slots</option>`).join('')}</select></label></div><hr><fieldset id="headliner-fields"><legend>Headliners & slot availability</legend><div id="slots-editor" class="slots-editor"></div><p class="helper">Assign an existing player, leave a slot open, or block it from being claimed.</p></fieldset><label class="wide check"><input type="checkbox" name="allow_stock" ${d.allow_stock?'checked':''}>Allow players without the loader (stock FUSER) to watch and book slots</label><hr><label>Custom event image</label><div class="image-control">${imageControl(d.image,'editor')}</div><p class="helper">Without a custom image, a headliner card is previewed automatically.</p></div><aside class="editor-preview"><div class="preview-caption">Event card preview</div><div id="event-live-preview"></div></aside></div>`;}else if(kind==='user'){body=`<div class="form-grid"><div class="wide"><h3>User ${d.id}</h3><p>${esc(d.platform)} · <span class="key">${esc(d.key)}</span></p></div>${fields(d,[['name','Display name','text','required maxlength="80"']])}<label>Presence<select name="online" disabled><option value="true" ${d.online?'selected':''}>Online</option><option value="false" ${!d.online?'selected':''}>Offline</option></select></label>${fields(d,[['notes','Admin notes','textarea','wide']])}<label class="check wide"><input name="banned" type="checkbox" ${d.banned?'checked':''}>Account banned</label></div>`;}else{body=`<div class="form-grid">${fields(d,[['username','Exact Epic username','text','required maxlength="80"'],['key','Epic login key','text','required'],['notes','Admin notes','textarea','wide']])}</div><p class="helper">Use the username from the ticket's dn claim and its Epic login key.</p>`;}$('editor-body').innerHTML=body+'<datalist id="catalogue-assets">'+(state.catalogue||[]).map(x=>`<option value="${esc(x.shortname)}">${esc(x.title)} · ${esc(x.artist)}</option>`).join('')+'</datalist><p id="editor-error" class="field-error" role="alert"></p>';if(kind==='event')renderSlots();if(kind==='item'){$('move-left').disabled=editing.index===0;$('move-right').disabled=editing.index===7;}updateEditorPreview();}
function syncDraft(){if(!editing)return;const f=$('editor-form');for(const [key,value] of new FormData(f)){if(key==='slotCount')continue;editing.draft[key]=['price','turn'].includes(key)?Number(value):key==='online'?value==='true':value;}if(editing.kind==='item')editing.draft.enabled=f.elements.enabled.checked;if(editing.kind==='user')editing.draft.banned=f.elements.banned.checked;if(editing.kind==='event')editing.draft.allow_stock=f.elements.allow_stock.checked;}
function renderSlots(){const d=editing.draft;$('headliner-fields').hidden=d.type==='maintenance';$('slot-count').disabled=d.type==='maintenance';$('slots-editor').innerHTML=d.slots.map((s,i)=>`<div class="slot-edit"><small>Slot ${i+1}</small><select aria-label="Headliner for slot ${i+1}" data-slot="${i}" ${s.blocked?'disabled':''}><option value="">Open slot</option>${state.users.filter(u=>!u.banned||u.id===s.user).map(u=>`<option value="${u.id}" ${u.id===s.user?'selected':''}>${esc(u.name)}${u.banned?' (banned)':''}</option>`).join('')}</select><label><input type="checkbox" data-block-slot="${i}" ${s.blocked?'checked':''}>Blocked</label></div>`).join('');}
function updateEditorPreview(){if(!editing)return;const {kind,draft:d}=editing;if(kind==='item')$('item-live-preview').innerHTML=`<div class="store-card featured" style="height:330px"><img src="${esc(d.image||art(d.title,editing.index))}" alt=""><div class="item-info"><strong>${esc(d.title||'Item name')}</strong><small>${esc(d.artist)}</small><span class="price">◇ ${d.price||0}</span></div></div>`;if(kind==='event')$('event-live-preview').innerHTML=d.image?`<img src="${esc(d.image)}" alt="Custom event image">`:generatedCard(d);}
$('editor-form').addEventListener('input',e=>{if(e.target.matches('[data-slot],[data-block-slot]'))return;syncDraft();if(editing.kind==='item'&&e.target.name==='shortname'){const asset=state.catalogue.find(x=>x.shortname.toLowerCase()===e.target.value.toLowerCase());if(asset){Object.assign(editing.draft,{id:asset.id,title:asset.title,artist:asset.artist,image:asset.image});renderEditor();}}updateEditorPreview();});
$('editor-form').addEventListener('change',e=>{syncDraft();if(editing.kind==='item'&&e.target.name==='assetId'){const asset=state.assets.find(a=>a.id===e.target.value);if(asset)Object.assign(editing.draft,{assetId:asset.id,id:asset.id,title:asset.title,artist:asset.artist,shortname:asset.shortname,image:asset.image});else Object.assign(editing.draft,{assetId:'',id:'',title:'',artist:'',shortname:'',image:''});renderEditor();return;}if(e.target.id==='slot-count'){const count=Number(e.target.value);if(count<editing.draft.slots.length&&editing.draft.slots.slice(count).some(s=>s.user||s.blocked)){confirmChange('Reduce headliner slots?','Assignments and blocks in the removed slots will be discarded.','Remove slots',()=>{editing.draft.slots.length=count;renderSlots();updateEditorPreview();});e.target.value=editing.draft.slots.length;}else{while(editing.draft.slots.length<count)editing.draft.slots.push({user:null,blocked:false});editing.draft.slots.length=count;renderSlots();}}if(e.target.matches('[data-slot]'))editing.draft.slots[Number(e.target.dataset.slot)].user=e.target.value?Number(e.target.value):null;if(e.target.matches('[data-block-slot]')){const slot=editing.draft.slots[Number(e.target.dataset.blockSlot)];slot.blocked=e.target.checked;if(slot.blocked)slot.user=null;renderSlots();}if(e.target.name==='type'){if(editing.draft.type!=='maintenance'&&!editing.draft.slots.length)editing.draft.slots=Array.from({length:4},()=>({user:null,blocked:false}));renderSlots();}updateEditorPreview();});
function validateTimes(d){if(!Number.isFinite(dateMs(d.start))||!Number.isFinite(dateMs(d.end)))return 'Choose valid start and end times.';if(dateMs(d.end)<=dateMs(d.start))return 'End time must be after start time.';return '';}
$('editor-form').onsubmit=async e=>{e.preventDefault();syncDraft();const {kind,draft:d,index}=editing;let error='';if(kind==='item'||kind==='event')error=validateTimes(d);if(kind==='event'){if(state.events.some(x=>!x.rotation&&x.id!==d.id&&dateMs(x.start)<dateMs(d.end)&&dateMs(x.end)>dateMs(d.start)))error='This event overlaps another scheduled event.';const users=d.type==='maintenance'?[]:d.slots.filter(s=>s.user).map(s=>s.user);if(new Set(users).size!==users.length)error='A headliner can occupy only one slot per event.';if(users.some(uid=>state.users.find(u=>u.id===uid)?.banned))error='Remove banned users from the headliner slots before saving.';if(d.type==='maintenance')d.slots=[];}if(kind==='exemption'){d.username=d.username.trim();d.key=d.key.trim();if(!d.username||!d.key)error='Username and Epic key are required.';if(state.exemptions.some(x=>x.id!==d.id&&x.key===d.key))error='An exemption already exists for this Epic key.';}if(kind==='user'){d.name=d.name.trim();if(!d.name)error='Display name is required.';}if(error){$('editor-error').textContent=error;return;}if(kind==='item'){const origin=editing.originIndex;if(origin!==index)state.items[origin]=state.items[index];state.items[index]=clone(d);}else{const list=state[{event:'events',user:'users',exemption:'exemptions'}[kind]],ix=list.findIndex(x=>x.id===d.id);if(!d.id)d.id=id();if(ix>=0)list[ix]=clone(d);else list.push(clone(d));}if(await save('Changes saved to the server.',editing.versions))closeEditor();else $('editor-error').textContent='Save failed. Your draft is still open; review the error and retry.';};
function closeEditor(){$('editor').close();editing=null;}$('editor').addEventListener('close',()=>editing=null);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeEditor);
function editEvent(eventId){const e=state.events.find(x=>x.id===eventId);openEditor('event',e||{id:'',name:'Diamond Stage',type:'event',start:relativeTime(8),end:relativeTime(9),turn:0,image:'',allow_stock:false,slots:Array.from({length:4},()=>({user:null,blocked:false}))});}
$('add-event').onclick=()=>editEvent();$('add-exemption').onclick=()=>openEditor('exemption',{id:'',username:'',key:'',notes:''});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.item!==undefined)openEditor('item',state.items[Number(d.item)],Number(d.item));if(d.event)editEvent(d.event);if(d.user)openEditor('user',state.users.find(u=>u.id===Number(d.user)));if(d.exemption)openEditor('exemption',state.exemptions.find(x=>x.id===d.exemption));if(d.removeEvent)confirmChange('Remove event?','This removes the event and all of its headliner assignments from the server.','Remove event',()=>{state.events=state.events.filter(x=>x.id!==d.removeEvent);save('Event removed.');});if(d.removeExemption)confirmChange('Remove exemption?','This Epic key will no longer be exempt on the server.','Remove exemption',()=>{state.exemptions=state.exemptions.filter(x=>x.id!==d.removeExemption);save('Exemption removed.');});if(d.ban){const u=state.users.find(x=>x.id===Number(d.ban));confirmChange(u.banned?'Unban user?':'Ban user?',u.name+' will '+(u.banned?'regain':'lose')+' access on this server.',u.banned?'Unban':'Ban',()=>{u.banned=!u.banned;if(u.banned)u.online=false;save(u.banned?'User banned in preview.':'User unbanned in preview.');});}if(d.duplicate){const item=clone(state.events.find(x=>x.id===d.duplicate));item.id='';item.name+=' (copy)';item.start=relativeTime(8);item.end=relativeTime(9);openEditor('event',item);}if(d.clearImage){if(d.clearImage==='editor'){syncDraft();editing.draft.image='';renderEditor();}else{promoDraft.image='';renderPromoImage();renderPromotionPreview();}}if(b.id==='clear-item')confirmChange('Clear store slot?','The slot stays in the eight-item layout and can be filled again.','Clear slot',()=>{const ix=editing.originIndex;state.items[ix]={id:id(),title:'',artist:'',shortname:'',price:0,enabled:false,start:relativeTime(-24),end:relativeTime(168),image:''};closeEditor();save('Slot cleared.');});if(b.id==='move-left'||b.id==='move-right'){syncDraft();const ix=editing.index,next=ix+(b.id==='move-left'?-1:1);editing.index=next;$('editor-title').textContent='Edit store slot '+(next+1);toast('New position: slot '+(next+1)+'. Save to apply.');renderEditor();}});
document.addEventListener('change',e=>{if(!e.target.dataset.upload)return;const input=e.target,file=input.files?.[0],target=input.dataset.upload,owner=editing;if(!file)return;if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>3*1024*1024){toast('Choose a PNG, JPEG, WebP or GIF under 3 MB.');input.value='';return;}const reader=new FileReader();reader.onload=()=>{if(target==='editor'){if(editing!==owner)return;syncDraft();editing.draft.image=reader.result;renderEditor();}else{promoDraft.image=reader.result;renderPromoImage();renderPromotionPreview();}};reader.readAsDataURL(file);});
for(const key of ['user-search','user-filter'])$(key).addEventListener('input',renderUsers);$('exemption-search').oninput=renderExemptions;$('schedule-filter').onchange=renderSchedule;
function newPromotion(){return {promotion_id:0,promotion_type:'hmx_promotion',name:'',message:'',extra_text:'',enabled:true,start:relativeTime(0),end:relativeTime(168),image:''};}function promoStatus(d){const active=d.enabled&&dateMs(d.start)<=Date.now()&&dateMs(d.end)>Date.now();return {live:active,label:!d.enabled?'Disabled':active?'Active now':dateMs(d.start)>Date.now()?'Scheduled':'Expired'};}function promoDirty(){return JSON.stringify(promoDraft)!==JSON.stringify(promoBase);}function withClean(fn){if(promoDirty())confirmChange('Discard edits?','Your unsaved changes to this promotion will be lost.','Discard edits',fn);else fn();}function fillPromotionForm(){const form=$('promotion-form');for(const [k,v]of Object.entries(promoDraft)){if(!form.elements[k])continue;if(k==='enabled')form.elements[k].checked=v;else form.elements[k].value=v;}const n=state.promotions.length;$('promotion-form-title').textContent=promoIndex<n?'Promotion '+(promoIndex+1)+' of '+n:'New promotion';renderPromoImage();renderPromotionList();renderPromotionPreview();}function loadPromotion(index=promoIndex){const list=state.promotions;promoIndex=Math.max(0,Math.min(Number(index)||0,list.length));promoDraft=promoIndex<list.length?clone(list[promoIndex]):newPromotion();promoBase=clone(promoDraft);promoVersion=state.versions?.promotions;$('promotion-error').textContent='';fillPromotionForm();}function renderPromotionList(){if(!promoDraft)return;const list=state.promotions,rows=list.map((p,i)=>{const d=i===promoIndex?promoDraft:p,st=promoStatus(d);return `<div class="promo-row${i===promoIndex?' selected':''}"><button type="button" class="promo-name" data-promo-select="${i}"><span>${i+1}</span>${esc(d.name||'Untitled promotion')}</button><span class="badge${st.live?' live':''}">${st.label}</span><small class="key">${p.promotion_id?'id '+p.promotion_id:'new'}</small><div class="actions"><button type="button" data-promo-move="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="Move up">↑</button><button type="button" data-promo-move="${i}" data-dir="1" ${i===list.length-1?'disabled':''} aria-label="Move down">↓</button><button type="button" class="danger" data-promo-remove="${i}">Remove</button></div></div>`;});if(promoIndex>=list.length)rows.push(`<div class="promo-row selected"><span class="promo-name"><span>${list.length+1}</span>${esc(promoDraft.name||'New promotion')}</span><span class="badge">Unsaved</span></div>`);$('promotion-list').innerHTML=rows.join('');$('add-promotion').disabled=list.length>=(state.max_promotions||8)||promoIndex>=list.length;}
function syncPromotion(){const f=$('promotion-form');for(const key of ['name','message','extra_text','start','end'])promoDraft[key]=f.elements[key].value;promoDraft.enabled=f.elements.enabled.checked;}
function renderPromoImage(){$('promo-image-control').innerHTML=imageControl(promoDraft.image,'promotion');}
function renderPromotionPreview(){if(!promoDraft)return;const d=promoDraft,st=promoStatus(d);$('promotion-status').textContent=st.label;$('promotion-status').className='badge'+(st.live?' live':'');const all=state.promotions.map((p,i)=>i===promoIndex?d:p);if(promoIndex>=state.promotions.length)all.push(d);const live=all.filter(p=>promoStatus(p).live),pips=(live.length?live:[d]).map(p=>`<span class="game-pip${p===d?'':' dim'}"></span>`).join('');$('promotion-preview').innerHTML=`<div class="game-promo" role="button" tabindex="0" aria-label="Show promotion: ${esc(d.name)}">${d.image?`<img src="${esc(d.image)}" alt="Promotion artwork">`:''}<div class="scrim"></div><div class="game-promo-copy"><h3>${esc(d.name||'Announcement title')}</h3><p>${esc(d.message)}</p></div></div><div class="game-promo-footer"><span class="game-pips" aria-label="Carousel position">${pips}</span><button type="button" id="show-game-promotion">↵ &nbsp; Show Promotion</button></div><p class="game-preview-meta">${d.extra_text.length} characters · ${d.extra_text.length>300?'Scrolling':'Text-only'} announcement popup</p>`;const tile=$('promotion-preview').querySelector('.game-promo');tile.onclick=showGamePromotion;tile.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showGamePromotion();}};$('show-game-promotion').onclick=showGamePromotion;requestAnimationFrame(fitPromotionText);}
function fitPromotionText(){const tile=$('promotion-preview').querySelector('.game-promo');if(!tile||!tile.clientWidth)return;for(const [selector,max,font] of [['h3',111,24],['p',104,16]]){const node=tile.querySelector(selector),scale=tile.clientWidth/570;node.style.fontSize=(font*scale)+'px';let size=font;while(node.scrollHeight>max*scale+1&&size>9){size-=.5;node.style.fontSize=(size*scale)+'px';}}}
window.addEventListener('resize',fitPromotionText);document.fonts.ready.then(fitPromotionText);
function showGamePromotion(){$('game-popup-title').textContent=promoDraft.name;$('game-popup-message').textContent=promoDraft.extra_text;$('game-popup-message').classList.toggle('scrolling',promoDraft.extra_text.length>300);$('game-promotion-popup').showModal();$('game-popup-message').scrollTop=0;}
$('game-popup-ok').onclick=()=>$('game-promotion-popup').close();
$('promotion-form').oninput=()=>{syncPromotion();renderPromotionList();renderPromotionPreview();};$('discard-promotion').onclick=()=>loadPromotion();$('add-promotion').onclick=()=>withClean(()=>loadPromotion(state.promotions.length));$('promotion-list').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.promoSelect!==undefined){const i=Number(d.promoSelect);if(i!==promoIndex)withClean(()=>loadPromotion(i));}if(d.promoMove!==undefined){const i=Number(d.promoMove),j=i+Number(d.dir);withClean(async()=>{const list=state.promotions;[list[i],list[j]]=[list[j],list[i]];promoIndex=j;await save('Promotion order saved.',{...baseline.versions,promotions:promoVersion});});}if(d.promoRemove!==undefined){const i=Number(d.promoRemove),name=state.promotions[i].name||'Untitled promotion';confirmChange('Remove promotion?',name+' leaves the FUSER main-menu carousel at the next main-menu visit.','Remove promotion',async()=>{state.promotions.splice(i,1);if(promoIndex>i||promoIndex>=state.promotions.length)promoIndex=Math.max(0,promoIndex-1);await save('Promotion removed.',{...baseline.versions,promotions:promoVersion});});}};$('promotion-form').onsubmit=async e=>{e.preventDefault();syncPromotion();let error=validateTimes(promoDraft);if(!promoDraft.name.trim()||!promoDraft.message.trim()||!promoDraft.extra_text.trim())error='Title, carousel description and full announcement are required.';if(error){$('promotion-error').textContent=error;return;}const draft=clone(promoDraft),revision=promoVersion,index=promoIndex;if(index<state.promotions.length)state.promotions[index]=clone(draft);else state.promotions.push(clone(draft));$('promotion-error').textContent='';if(!await save('Promotion saved to the server.',{...baseline.versions,promotions:revision})){promoIndex=Math.min(index,state.promotions.length);promoDraft=draft;promoVersion=revision;fillPromotionForm();$('promotion-error').textContent='Save failed. Your draft is preserved. Discard edits to reload the latest promotions.';}};
$('reset').onclick=()=>refresh().catch(error=>toast(error.message));$('logout').onclick=async()=>{try{await request('auth/logout','POST',{});location.reload();}catch(error){toast(error.message);}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fuser-control.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Control data exported.');};
document.querySelector('.shell').inert=true;refresh().then(async()=>{const admin=await request('auth/session');document.querySelector('.sidebar-footer strong').textContent=admin.name;document.querySelector('.sidebar-footer p').textContent='Admin ID: '+admin.id;}).catch(error=>toast(error.message)).finally(()=>{document.querySelector('.shell').inert=false;activate('status');});

