$('asset-package').onchange=e=>{const file=e.target.files?.[0],f=$('asset-upload-form');if(file&&!f.elements.title.value)f.elements.title.value=file.name.replace(/\.(pak|zip)$/i,'').replace(/_P$/i,'').replaceAll('_',' ');};
$('asset-art').onchange=e=>{const file=e.target.files?.[0];if(!file)return;if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>3*1024*1024){$('asset-upload-error').textContent='Choose a PNG, JPEG, WebP or GIF under 3 MB.';e.target.value='';return;}const reader=new FileReader();reader.onload=()=>{let img=$('asset-art-control').querySelector('img');if(!img){img=document.createElement('img');img.alt='Asset artwork preview';$('asset-art-control').prepend(img);}img.src=reader.result;$('asset-art-control').querySelector('p').hidden=true;};reader.readAsDataURL(file);};
let uploadingAsset=false;
$('asset-upload-form').onsubmit=async e=>{e.preventDefault();if(uploadingAsset)return;uploadingAsset=true;const form=e.target,button=form.querySelector('[type="submit"]'),data=new FormData(form);for(const field of ['signature','artwork'])if(!data.get(field)?.name)data.delete(field);button.disabled=true;button.textContent='Uploading…';$('asset-upload-error').textContent='';try{const response=await fetch('/control/api/assets',{method:'POST',credentials:'same-origin',body:data});if(response.status===401){location.reload();return;}const result=await response.json();if(!response.ok)throw new Error(result.error||'Upload failed');form.reset();$('asset-art-control').querySelector('img')?.remove();$('asset-art-control').querySelector('p').hidden=false;await refresh();toast('Asset uploaded. Choose it in a Diamond Store offer to publish it.');}catch(error){$('asset-upload-error').textContent=error.message;}finally{uploadingAsset=false;button.disabled=false;button.textContent='Add to asset library';}};
document.addEventListener('click',e=>{const button=e.target.closest('[data-remove-asset]');if(!button)return;const asset=state.assets.find(a=>a.id===button.dataset.removeAsset);if(!asset||state.items.some(it=>it.assetId===asset.id))return;confirmChange('Remove asset from library?',asset.title+' will be archived. Downloads for existing owners remain available.','Archive asset',async()=>{try{await request('api/assets/'+encodeURIComponent(asset.id),'DELETE',undefined,baseline.versions.assets_hidden);await refresh();toast('Asset archived.');}catch(error){toast(error.message);}});});

const wallText=s=>s?s.replace('T',' '):'—';
function renderAdmins(){$('admin-stats').innerHTML=[['Administrators',admins.admins.length],['Pending invitations',admins.tokens.length]].map(([t,n])=>`<div class="stat"><strong>${n}</strong><span>${t}</span></div>`).join('');$('admin-list').innerHTML=admins.admins.map(a=>{const self=a.id===admins.self;return `<tr><td><strong>${esc(a.name)}</strong>${self?' <span class="badge live">You</span>':''}<small class="key">${esc(a.id)}</small></td><td>${esc(wallText(a.created))}</td><td>${esc(a.created_by||'—')}</td><td>${esc(wallText(a.last_login))}</td><td><div class="actions"><button class="danger" data-revoke-admin="${esc(a.id)}" ${self?'disabled title="You cannot remove yourself"':''}>Remove</button></div></td></tr>`;}).join('')||'<tr><td colspan="5">No administrators.</td></tr>';$('token-list').innerHTML=admins.tokens.map(t=>`<tr><td><strong>${esc(t.name)}</strong></td><td class="key">${esc(t.id)}</td><td>${esc(t.created_by||'—')}</td><td>${esc(wallText(t.expires))}</td><td><div class="actions"><button class="danger" data-cancel-token="${esc(t.id)}">Cancel</button></div></td></tr>`).join('')||'<tr><td colspan="5">No pending invitations.</td></tr>';renderAudit();}
function renderAudit(){const query=$('audit-search').value.toLowerCase(),list=admins.audit.filter(e=>[e.admin,e.action,e.target,e.detail,e.ip].join(' ').toLowerCase().includes(query));$('audit-list').innerHTML=list.map(e=>`<tr><td>${esc(wallText(e.at))}</td><td><strong>${esc(e.admin||'—')}</strong>${e.admin_id&&e.admin_id!=='cli'?`<small class="key">${esc(e.admin_id.slice(0,12))}…</small>`:''}</td><td class="key">${esc(e.action)}</td><td class="key">${esc(e.target)}</td><td>${esc(e.detail)}</td><td class="key">${esc(e.ip||'—')}</td></tr>`).join('')||'<tr><td colspan="6">No audit entries match.</td></tr>';}
async function refreshAdmins(){admins=await request('api/admins');renderAdmins();}
$('audit-search').oninput=renderAudit;
document.addEventListener('click',e=>{const b=e.target.closest('[data-revoke-admin],[data-cancel-token]');if(!b||b.disabled)return;if(b.dataset.revokeAdmin){const a=admins.admins.find(x=>x.id===b.dataset.revokeAdmin);if(!a)return;confirmChange('Remove administrator?',a.name+' loses access immediately: their sessions end and any invitations they issued are cancelled.','Remove administrator',async()=>{try{await request('api/admins/'+encodeURIComponent(a.id),'DELETE');toast(a.name+' removed.');}catch(error){toast(error.message);}refreshAdmins().catch(error=>toast(error.message));});}else{const t=admins.tokens.find(x=>x.id===b.dataset.cancelToken);if(!t)return;confirmChange('Cancel invitation?','The enrollment token for '+t.name+' will stop working.','Cancel invitation',async()=>{try{await request('api/admins/tokens/'+encodeURIComponent(t.id),'DELETE');toast('Invitation cancelled.');}catch(error){toast(error.message);}refreshAdmins().catch(error=>toast(error.message));});}});
function inviteStep(token){$('invite-step-create').hidden=token;$('invite-step-token').hidden=!token;$('invite-submit').hidden=token;$('invite-copy').hidden=!token;$('invite-done').hidden=!token;}
$('invite-admin').onclick=()=>{$('invite-form').reset();$('invite-token').value='';$('invite-error').textContent='';inviteStep(false);$('invite-dialog').showModal();};
$('invite-close').onclick=$('invite-done').onclick=()=>$('invite-dialog').close();
