$('invite-dialog').addEventListener('close',()=>{$('invite-token').value='';inviteStep(false);});
$('invite-form').onsubmit=async e=>{e.preventDefault();if(!$('invite-step-token').hidden)return;const f=e.target,name=f.elements.name.value.trim(),button=$('invite-submit');if(!name){$('invite-error').textContent='Enter the administrator’s name.';return;}button.disabled=true;$('invite-error').textContent='';try{const r=await request('api/admins/tokens','POST',{name,minutes:Number(f.elements.minutes.value)});$('invite-for').textContent=name;$('invite-expires').textContent=wallText(r.expires);$('invite-token').value=r.token;inviteStep(true);$('invite-token').select();refreshAdmins().catch(error=>toast(error.message));}catch(error){$('invite-error').textContent=error.message;}finally{button.disabled=false;}};
$('invite-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('invite-token').value);toast('Token copied. It will not be shown again.');}catch{$('invite-token').select();toast('Copy failed; the token is selected for copying by hand.');}};
// Community songs. The server filters, sorts and pages (api/community); the panel holds one page. Import uploads the
// file for a dry run, then again to apply it, so the result always reflects the table as it is then.
const communityQuery={q:'',state:'all',kind:'all',sort:'updated',page:1,size:50},COMMUNITY_IMPORT_MAX=32<<20,COMMUNITY_ROWS_SHOWN=200,COMMUNITY_RESULTS=['added','updated','unchanged','kept','refused'],COMMUNITY_CLS={added:'add',updated:'update',unchanged:'same',kept:'keep',refused:'refuse'};
let community=null,communitySeq=0,communityEditing=null,communityPlan=null,communityFilter=null,communityFile=null,communitySearchTimer=null;
const num=n=>Number(n||0).toLocaleString('en-US'),compactCount=n=>n<1000?String(n).padStart(2,'0'):new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(n),sizeText=n=>n>=1<<20?(n/1048576).toFixed(1)+' MB':n>=1024?Math.round(n/1024)+' KB':n+' B',wallMinute=s=>s?s.slice(0,16).replace('T',' '):'—';
function renderCommunityNav(n){if(n===undefined)return;$('community-nav-count').textContent=compactCount(n);$('community-nav-count').title=num(n)+' community songs';}
async function loadCommunity(){const seq=++communitySeq;$('community-count').textContent='Loading…';try{const v=await request('api/community?'+new URLSearchParams(communityQuery));if(seq!==communitySeq)return;community=v;communityQuery.page=v.page;renderCommunity();}catch(error){if(seq===communitySeq)$('community-count').textContent='Could not load community songs: '+error.message;}}
function renderCommunity(){const v=community,st=v.stats,filtered=communityQuery.q||communityQuery.state!=='all'||communityQuery.kind!=='all',from=(v.page-1)*v.size;renderCommunityNav(st.songs);$('community-stats').innerHTML=[['Songs',st.songs],['Enabled',st.enabled],['Disabled',st.disabled],['Archives',st.archives],['Folders',st.folders],['With failed reports',st.failing]].map(([l,n])=>`<div class="stat"><strong>${num(n)}</strong><span>${l}</span></div>`).join('');$('community-count').textContent=filtered?`${num(v.matched)} of ${num(st.songs)} songs match`:`${num(st.songs)} songs`;$('community-page-range').textContent=v.matched?`Showing ${num(from+1)}–${num(from+v.items.length)} of ${num(v.matched)}`:'No matches';$('community-page-input').value=v.page;$('community-page-total').textContent=num(v.pages);$('community-page-first').disabled=$('community-page-prev').disabled=v.page<=1;$('community-page-next').disabled=$('community-page-last').disabled=v.page>=v.pages;$('community-list').innerHTML=v.items.map(communityRow).join('')||`<tr><td colspan="7" class="empty">${filtered?'No community songs match these filters.':'No community songs yet. Add one or import a batch.'}</td></tr>`;}
function communityRow(s){const x=esc(s.x),size=(s.files||[]).reduce((n,f)=>n+f.size,0);return `<tr class="${s.disabled?'is-disabled':''}"><td class="c-song"><button class="song-title" data-community-edit="${x}">${esc(s.title||'(untitled)')}</button><small>${esc(s.artist)}</small></td><td class="c-x key">${x}</td><td class="c-creator">${esc(s.creator)}</td><td class="c-source"><span class="badge">${s.kind==='archive'?esc(s.archive):'folder'}</span><small>${sizeText(size)}</small></td><td class="c-reports"><div class="badges">${s.reports_ok+s.reports_failed?`${s.reports_ok?`<span class="badge ok">${num(s.reports_ok)} ok</span>`:''}${s.reports_failed?`<span class="badge bad">${num(s.reports_failed)} failed</span>`:''}`:'<small>No reports yet</small>'}</div></td><td class="c-state">${s.disabled?`<span class="badge banned"><span class="dot"></span>Disabled</span><div class="reason">${esc(s.disabled_reason)}</div>`:'<span class="badge live"><span class="dot"></span>Enabled</span>'}<small class="updated">${esc(wallMinute(s.updated))}</small></td><td class="c-actions"><div class="actions"><button data-community-edit="${x}">Edit</button>${s.disabled?`<button data-community-enable="${x}">Enable</button>`:`<button data-community-disable="${x}">Disable</button>`}</div></td></tr>`;}
function communityGo(page){communityQuery.page=page;loadCommunity();}
$('community-search').oninput=()=>{clearTimeout(communitySearchTimer);communitySearchTimer=setTimeout(()=>{communityQuery.q=$('community-search').value.trim();communityGo(1);},250);};
for(const [id,key] of [['community-state','state'],['community-kind','kind'],['community-sort','sort'],['community-page-size','size']])$(id).onchange=()=>{communityQuery[key]=$(id).value;communityGo(1);};
$('community-page-first').onclick=()=>communityGo(1);$('community-page-prev').onclick=()=>communityGo(communityQuery.page-1);$('community-page-next').onclick=()=>communityGo(communityQuery.page+1);$('community-page-last').onclick=()=>communityGo(community?.pages||1);
$('community-page-input').onchange=()=>communityGo(Math.max(1,Math.floor(Number($('community-page-input').value))||1));
$('community-export').onclick=()=>{const a=document.createElement('a');a.href='/control/api/community-export';a.click();};

// The editor's checks mirror community.Song.Validate; the server repeats them and also refuses official and taken shortnames.
const communityForm=$('community-form');
function communityChecks(s){const out=[],add=(label,ok)=>out.push([label,ok]),x=s.x||'',pak=x+'_P.pak',sig=x+'_P.sig',entryOK=(e,want)=>{if(!e||e.startsWith('/')||/[\\:]/.test(e))return false;const p=e.split('/');return p.every(q=>q&&q!=='.'&&q!=='..')&&p[p.length-1].toLowerCase()===want.toLowerCase();};add('Shortname: letters, digits, _ and -, at most 64',/^[A-Za-z0-9_-]{1,64}$/.test(x));add('Not credited to Harmonix',!/harmonix/i.test(s.creator||''));let url=null;try{url=new URL(s.link);}catch{}add('Link is an http(s) URL',!!url&&/^https?:$/.test(url.protocol));add('Drive file IDs, sizes (up to 128 MB) and names',s.files.length>0&&s.files.every(f=>/^[A-Za-z0-9_-]{10,128}$/.test(f.id)&&f.size>0&&f.size<=128*1048576&&f.name&&!/[\/\\]/.test(f.name)));if(s.kind==='archive'){add('Archive format zip, rar4 or rar5',['zip','rar4','rar5'].includes(s.archive));add('Pak path ends in '+(x?pak:'<X>_P.pak'),entryOK(s.pak_entry,pak));add('Sig path ends in '+(x?sig:'<X>_P.sig'),entryOK(s.sig_entry,sig));}else if(s.kind==='folder')add('Files named '+(x?pak+' and '+sig:'<X>_P.pak and <X>_P.sig'),s.files.length===2&&s.files[0].name.toLowerCase()===pak.toLowerCase()&&s.files[1].name.toLowerCase()===sig.toLowerCase());else add('Source is archive or folder',false);return out;}
function communitySetKind(kind){communityForm.elements.kind.value=kind;$('community-source-archive').hidden=kind!=='archive';$('community-source-folder').hidden=kind!=='folder';}
function communityFill(s){const f=communityForm.elements,files=s.files||[],put=(p,i)=>{f[p+'_id'].value=files[i]?.id||'';f[p+'_size'].value=files[i]?.size||'';f[p+'_name'].value=files[i]?.name||'';};for(const k of ['x','creator','artist','title','link','archive','pak_entry','sig_entry','submitted','sheet','note'])f[k].value=s[k]||'';if(!f.archive.value)f.archive.value='zip';if(s.kind==='folder'){put('p',0);put('s',1);put('a',9);}else{put('a',0);put('p',9);put('s',9);}communitySetKind(s.kind||'archive');}
function communityRead(){const f=communityForm.elements,v=k=>f[k].value.trim(),file=p=>({id:v(p+'_id'),name:v(p+'_name'),size:Number(v(p+'_size'))||0}),kind=f.kind.value;return {x:v('x'),kind,archive:kind==='archive'?v('archive'):'',files:kind==='archive'?[file('a')]:[file('p'),file('s')],pak_entry:kind==='archive'?v('pak_entry'):'',sig_entry:kind==='archive'?v('sig_entry'):'',link:v('link'),artist:v('artist'),title:v('title'),creator:v('creator'),submitted:v('submitted'),sheet:v('sheet'),note:f.note.value.trim()};}
function communityRefresh(){const s=communityRead(),list=communityChecks(s);$('community-checks').innerHTML=list.map(([l,ok])=>`<li class="${ok?'':'fail'}">${esc(l)}</li>`).join('');$('community-json').textContent=JSON.stringify(s);$('community-x-hint').textContent=s.x?`Crate path /Game/DLC/Songs/${s.x}/Meta_${s.x}`:'The crate path is /Game/DLC/Songs/<X>/Meta_<X>.';for(const k of ['a_size','p_size','s_size']){const n=Number(communityForm.elements[k].value);communityForm.elements[k].title=n?sizeText(n):'';}$('community-error').textContent='';return list.every(c=>c[1]);}
function communityHistory(d){const s=d.song;return `<h3>Loader reports <small style="font-weight:400;color:var(--muted)">· ${num(s.reports_ok)} ok, ${num(s.reports_failed)} failed</small></h3>${d.reports.length?`<div class="report-list">${d.reports.slice(0,8).map(r=>`<div><span>${r.ok?'<span class="badge ok">ok</span>':'<span class="badge bad">failed</span>'} ${esc(r.reason)}</span><small>${esc(wallMinute(r.at))}</small></div>`).join('')}</div>`:'<p class="hint">No player has installed it yet.</p>'}<div class="meta-list" style="margin-top:14px"><span>Added ${esc(wallMinute(s.added))} · updated ${esc(wallMinute(s.updated))}</span>${d.seen_sha256.length?`<span>Good pak SHA-256: <span class="key">${d.seen_sha256.map(h=>esc(h.slice(0,12))+'…').join(', ')}</span></span>`:''}${s.disabled?`<span style="color:var(--red)">Disabled: ${esc(s.disabled_reason)}</span>`:''}${d.in_catalogue?'<span>The catalogue also has this shortname and answers first.</span>':''}</div>`;}
async function openCommunityEditor(x){let detail=null;if(x){try{detail=await request('api/community/'+encodeURIComponent(x));}catch(error){toast(error.message);return;}}const s=detail?.song;communityEditing=detail;$('community-editor-title').textContent=s?'Edit '+(s.title||s.x):'Add community song';$('community-save').textContent=s?'Save changes':'Add song';communityForm.elements.x.readOnly=!!s;communityForm.elements.x.title=s?'The shortname identifies the entry; remove it and add it again to change it':'';communityFill(s||{kind:'archive',archive:'zip',files:[]});const ex=s?esc(s.x):'';$('community-secondary').innerHTML=s?`${s.disabled?`<button type="button" data-community-enable="${ex}">Enable</button>`:`<button type="button" data-community-disable="${ex}">Disable</button>`}<button type="button" class="danger" data-community-remove="${ex}">Remove</button>`:'';$('community-history').hidden=!s;$('community-history').innerHTML=s?communityHistory(detail):'';$('community-save-hint').hidden=!s;communityRefresh();$('community-editor').showModal();(s?communityForm.elements.creator:communityForm.elements.x).focus();}
communityForm.addEventListener('input',communityRefresh);
communityForm.querySelectorAll('input[name=kind]').forEach(r=>r.onchange=()=>{communitySetKind(r.value);communityRefresh();});
$('community-fill-link').onclick=()=>{const link=communityForm.elements.link.value,m=link.match(/\/file\/d\/([A-Za-z0-9_-]{10,128})/)||link.match(/[?&]id=([A-Za-z0-9_-]{10,128})/);if(!m){toast('That link has no Drive file ID (folder links list two files; enter them below).');return;}communitySetKind('archive');communityForm.elements.a_id.value=m[1];communityRefresh();toast('File ID copied from the link.');};
$('community-default-entries').onclick=()=>{const f=communityForm.elements,x=f.x.value.trim(),dir=p=>p.includes('/')?p.slice(0,p.lastIndexOf('/')+1):'';if(!x){toast('Enter the shortname first.');return;}const pak=f.pak_entry.value;f.pak_entry.value=dir(pak)+x+'_P.pak';f.sig_entry.value=dir(f.sig_entry.value||pak)+x+'_P.sig';communityRefresh();};
$('community-copy-json').onclick=async()=>{try{await navigator.clipboard.writeText($('community-json').textContent);toast('Entry JSON copied.');}catch{toast('Copy failed.');}};
communityForm.onsubmit=async e=>{e.preventDefault();if(!communityRefresh()){$('community-error').textContent='Fix the failed checks first.';return;}const s=communityRead(),button=$('community-save');button.disabled=true;try{const r=communityEditing?await request('api/community/'+encodeURIComponent(s.x),'PUT',s):await request('api/community','POST',s);$('community-editor').close();toast((r.result==='added'?'Added ':r.result==='updated'?'Updated ':'No changes to ')+s.x+'.'+(r.in_catalogue?' The catalogue also has this shortname and answers first.':''));loadCommunity();}catch(error){$('community-error').textContent=error.message;}finally{button.disabled=false;}};
async function communityAction(x,path,method,body,message){try{await request('api/community/'+encodeURIComponent(x)+path,method,body);if($('community-editor').open)$('community-editor').close();toast(message);}catch(error){toast(error.message);}loadCommunity();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.dialogClose!==undefined)b.closest('dialog').close();if(d.communityEdit)openCommunityEditor(d.communityEdit);if(d.communityEnable)communityAction(d.communityEnable,'/enable','POST',{},'Enabled '+d.communityEnable+'.');if(d.communityDisable){const x=d.communityDisable;confirmChange('Disable '+x+'?','The server stops offering this song to loaders. Players who already installed it keep it.','Disable',()=>communityAction(x,'/disable','POST',{reason:$('confirm-reason').value.trim()},'Disabled '+x+'.'));$('confirm-reason').value='disabled by an operator';$('confirm-reason-wrap').hidden=false;}if(d.communityRemove){const x=d.communityRemove;confirmChange('Remove '+x+'?','The entry and its loader reports are deleted. Re-adding it starts from scratch; Disable keeps the history.','Remove',()=>communityAction(x,'','DELETE',undefined,'Removed '+x+'.'));}});
$('community-add').onclick=()=>openCommunityEditor(null);

// Bulk import: a dry run on choosing the file or changing the mode, then the same upload applied.
function communityImportReset(){communityFile=null;communityPlan=null;communityFilter=null;$('community-import-file').value='';$('community-dropzone').hidden=false;$('community-loaded').hidden=true;$('community-import-results').hidden=true;$('community-apply-import').disabled=true;$('community-apply-import').textContent='Apply import';$('community-import-note').textContent='Nothing changes until you apply.';}
async function communityUpload(dryRun){const f=communityFile,mode=document.querySelector('input[name=community-import-mode]:checked').value,format=/\.jsonl$/i.test(f.name)?'jsonl':/\.json$/i.test(f.name)?'json':'';const response=await fetch('/control/api/community-import?'+new URLSearchParams({mode,dry_run:dryRun?'1':'0',format,name:f.name}),{method:'POST',credentials:'same-origin',headers:{'Content-Type':format==='json'?'application/json':'application/x-ndjson'},body:f});if(response.status===401){location.reload();throw new Error('Sign in required');}const data=await response.json();if(!response.ok)throw new Error(data.error||'Import failed');return data;}
async function communityDryRun(){if(!communityFile)return;$('community-apply-import').disabled=true;$('community-import-note').textContent='Checking the file…';try{communityPlan=await communityUpload(true);renderCommunityImport();}catch(error){communityPlan=null;$('community-import-results').hidden=true;$('community-import-note').textContent=error.message;}}
function renderCommunityImport(){const p=communityPlan,c=p.counts;if(communityFilter&&!c[communityFilter])communityFilter=null;$('community-import-summary').innerHTML=COMMUNITY_RESULTS.map(r=>`<button type="button" class="badge ${COMMUNITY_CLS[r]}" data-community-result="${r}" aria-pressed="${communityFilter===r}" ${c[r]?'':'disabled'}>${num(c[r])} ${r}</button>`).join('');const rows=p.rows.filter(r=>communityFilter?r.result===communityFilter:r.result!=='unchanged'),shown=rows.slice(0,COMMUNITY_ROWS_SHOWN);$('community-import-rows').innerHTML=shown.map(r=>`<tr><td>${esc(r.line)}</td><td class="key">${esc(r.x||'—')}</td><td><span class="badge ${COMMUNITY_CLS[r.result]}">${r.result}</span></td><td>${esc(r.detail)}</td></tr>`).join('')||`<tr><td colspan="4">Every entry is unchanged.</td></tr>`;$('community-import-cap').textContent=(rows.length>shown.length?`Showing the first ${num(shown.length)} of ${num(rows.length)} ${communityFilter?communityFilter+' entries':'changes and problems'}. `:'')+(communityFilter?'Pick the chip again to show everything but unchanged entries.':c.unchanged?`${num(c.unchanged)} unchanged entries are hidden; pick the chip to list them.`:'');$('community-import-results').hidden=false;const n=c.added+c.updated;$('community-apply-import').disabled=!n;$('community-apply-import').textContent=n?`Apply ${num(n)} change${n>1?'s':''}`:'Nothing to apply';$('community-import-note').textContent=c.refused?`${num(c.refused)} refused entr${c.refused>1?'ies are':'y is'} skipped; the rest can still be applied.`:'Nothing changes until you apply.';}
function communityChoose(file){if(!file)return;if(file.size>COMMUNITY_IMPORT_MAX){toast('The file is larger than 32 MB.');return;}communityFile=file;communityFilter=null;$('community-dropzone').hidden=true;$('community-loaded').hidden=false;$('community-loaded-name').innerHTML=`<strong>${esc(file.name)}</strong> <small style="display:inline;color:var(--muted)">· ${sizeText(file.size)}</small>`;communityDryRun();}
$('community-open-import').onclick=()=>{communityImportReset();$('community-import-dialog').showModal();};
$('community-clear-file').onclick=communityImportReset;
$('community-import-file').onchange=e=>communityChoose(e.target.files?.[0]);
document.querySelectorAll('input[name=community-import-mode]').forEach(r=>r.onchange=communityDryRun);
$('community-import-summary').onclick=e=>{const b=e.target.closest('[data-community-result]');if(!b)return;communityFilter=communityFilter===b.dataset.communityResult?null:b.dataset.communityResult;renderCommunityImport();};
for(const t of ['dragenter','dragover'])$('community-dropzone').addEventListener(t,e=>{e.preventDefault();$('community-dropzone').classList.add('over');});
for(const t of ['dragleave','drop'])$('community-dropzone').addEventListener(t,e=>{e.preventDefault();$('community-dropzone').classList.remove('over');});
$('community-dropzone').addEventListener('drop',e=>communityChoose(e.dataTransfer.files?.[0]));
$('community-apply-import').onclick=async()=>{const button=$('community-apply-import');button.disabled=true;$('community-import-note').textContent='Importing…';try{const r=await communityUpload(false);$('community-import-dialog').close();toast(`Import applied: ${num(r.counts.added)} added, ${num(r.counts.updated)} updated${r.counts.refused?`, ${num(r.counts.refused)} refused`:''}.`);loadCommunity();}catch(error){$('community-import-note').textContent=error.message;button.disabled=false;}};
